 c<<[name,'sporadic',ns+'.Model',models[i],params,orders[i],o,s,nodes.key?(f) ? f : 'finite instance; see exact model and order',nc,status,status,status,status,'PROPERTIES.csv',status,nodes[o]['module'].tr('.','/')+'.lean','actual internal construction; comparisons/embeddings separately in PROPERTIES.csv; no general recognition/classification uniqueness claimed']
end
